    expect(timed).toHaveLength(1511 + 14 + 3 + 13 + 26 + 24 + 9);
    expect(timed.filter((item) => item.isTerminal && item.isCorrect)).toHaveLength(155 + 4 + 1 + 3 + 9 + 8 + 3);
